from pathlib import Path
p=Path('app.py')
s=p.read_text()
# Add HTTP/json stdlib only; no new dependency.
s=s.replace('import yfinance as yf\n','import yfinance as yf\nimport json\nimport urllib.parse\nimport urllib.request\n',1)
# Replace local-only GOVI loader with SARB primary + repository fallback, preserving serialisable cache payload.
start=s.index('@st.cache_data(show_spinner=False)\ndef load_govi_history():')
end=s.index('\ndef _normalise_stxgvi_close',start)
new='''@st.cache_data(ttl=3600,show_spinner=False)\ndef load_sarb_series(code):\n url='https://custom.resbank.co.za/SarbWebApi/WebIndicators/Shared/GetTimeseriesObservations/'+urllib.parse.quote(code)\n with urllib.request.urlopen(url,timeout=20) as r: payload=json.loads(r.read().decode('utf-8'))\n rows=payload if isinstance(payload,list) else payload.get('data',payload.get('observations',[]))\n vals=[]\n for row in rows:\n  if not isinstance(row,dict): continue\n  dt=row.get('date') or row.get('Date') or row.get('period') or row.get('Period')\n  val=row.get('value') if 'value' in row else row.get('Value')\n  try: vals.append((pd.to_datetime(dt),float(val)))\n  except Exception: pass\n if len(vals)<2: raise RuntimeError(f'SARB returned insufficient observations for {code}')\n return pd.Series(dict(vals),name=code).sort_index()\n\n@st.cache_data(show_spinner=False)\ndef load_govi_history():\n try:\n  s=load_sarb_series('KBP2013M').rename('GOVI')\n  if len(s)>=100: return s\n except Exception: pass\n d=pd.read_csv('govi_monthly.csv'); d['Date']=pd.to_datetime(d['Date'])+pd.offsets.MonthEnd(0)\n s=pd.Series(pd.to_numeric(d['SA_BONDS'],errors='coerce').values,index=d['Date'],name='GOVI').dropna().sort_index()\n if len(s)<100: raise RuntimeError('Validated GOVI history is incomplete')\n return s\n'''
s=s[:start]+new+s[end:]
# Registry metadata: full names survive selection and attribution.
anchor='@st.cache_data(ttl=3600,show_spinner=False)\ndef search_assets(query):'
pos=s.index(anchor)
registry='''@st.cache_data(ttl=3600,show_spinner=False)\ndef instrument_name(symbol):\n if symbol=='GOVI': return 'South African Government Bond Index'\n try:\n  q=yf.Search(symbol,max_results=8,news_count=0,lists_count=0,recommended=0)\n  for row in (getattr(q,'quotes',None) or []):\n   if str(row.get('symbol','')).upper()==symbol.upper(): return str(row.get('longname') or row.get('shortname') or symbol)\n except Exception: pass\n return symbol\n\n'''
s=s[:pos]+registry+s[pos:]
# SARB searchable known portfolio series alongside market search. Search remains extensible and source-labelled.
s=s.replace(" out=[]\n if 'govi' in q.lower() or 'south african government' in q.lower():\n  out.append({'symbol':'GOVI','name':'South African Government Bond Index (repository series)','source':'Repository'})", " out=[]\n sarb_catalog=[{'symbol':'GOVI','name':'South African Government Bond Index','source':'SARB / repository','code':'KBP2013M'}]\n for row in sarb_catalog:\n  if q.lower() in row['name'].lower() or q.lower() in row['symbol'].lower() or q.lower() in row['code'].lower(): out.append(row)",1)
# Search result interaction: click a full-name result directly; stored selection remains ticker/series only.
old='''if results:\n labels=[f\"{r['name']} | {r['symbol']} | {r['source']}\" for r in results]\n chosen_label=st.selectbox('Search results',labels,key='asset_search_result')\n chosen=results[labels.index(chosen_label)]['symbol']\n if st.button('Add asset',key='add_asset') and chosen not in st.session_state.selected_assets:\n  st.session_state.selected_assets.append(chosen); st.rerun()'''
new='''if results:\n st.caption('Search results')\n for i,r0 in enumerate(results):\n  if st.button(f\"{r0['name']} — {r0['symbol']}  ·  {r0['source']}\",key=f\"asset_result_{i}_{r0['symbol']}\",use_container_width=True):\n   if r0['symbol'] not in st.session_state.selected_assets: st.session_state.selected_assets.append(r0['symbol'])\n   st.rerun()'''
if old not in s: raise SystemExit('search UI anchor missing')
s=s.replace(old,new,1)
# Attribution gets full instrument name + identifier.
s=s.replace("attr.append({'Ticker':a0,'Total Return':total,'Capital Gain':cap,'Income / Distributions':inc,'Capital Gain % of Total':cap/total if not np.isclose(total,0) else np.nan,'Income % of Total':inc/total if not np.isclose(total,0) else np.nan})", "attr.append({'Instrument Name':instrument_name(a0),'Ticker / Series':a0,'Total Return':total,'Capital Gain':cap,'Income / Distributions':inc,'Capital Gain % of Total':cap/total if not np.isclose(total,0) else np.nan,'Income % of Total':inc/total if not np.isclose(total,0) else np.nan})",1)
s=s.replace("for c0 in at.columns[1:]: at[c0]=at[c0].map(lambda x:f'{x:.2%}' if pd.notna(x) else 'N/A')", "for c0 in ['Total Return','Capital Gain','Income / Distributions','Capital Gain % of Total','Income % of Total']: at[c0]=at[c0].map(lambda x:f'{x:.2%}' if pd.notna(x) else 'N/A')",1)
# Replace incomplete LaTeX dialog with full page calculation audit trail.
ls=s.index("@st.dialog('Full Calculation Workings'")
le=s.index("\n@st.dialog('Full Data Audit'",ls)
latex='''@st.dialog('Full Calculation Workings',width='large')\ndef show_latex_report():\n st.title('Complete Calculation Workings')\n st.caption(f'Current run: {prices.index[0]:%Y-%m-%d} to {prices.index[-1]:%Y-%m-%d}; {frequency}; RF={RF:.4%}; dividend reinvestment={REINVEST}; mode={mode}.')\n sections=[\n ('Raw total return',r'r_{a,t}=\\frac{P_{a,t}-P_{a,t-1}+D_{a,t}}{P_{a,t-1}}','Raw Close is used; explicit cash distributions are added separately. Adjusted Close is not used.'),\n ('Holding-period return',r'R_a=\\frac{P_{a,T}-P_{a,0}+\\sum_{t=1}^{T}D_{a,t}}{P_{a,0}}','Non-reinvested asset total return.'),\n ('Capital / income decomposition',r'R_a=R_a^{cap}+R_a^{inc},\\quad R_a^{cap}=\\frac{P_T-P_0}{P_0},\\quad R_a^{inc}=\\frac{\\sum D_t}{P_0}','Attribution shares divide each component by total return.'),\n ('Initial units',r'n_{a,0}=\\frac{w_aV_0}{P_{a,0}}','Initial nominal allocation divided by starting raw price.'),\n ('Cash distributions',r'C_{a,t}=C_{a,t-1}+n_{a,t-1}D_{a,t}','Used when reinvestment is off.'),\n ('Distribution reinvestment',r'n_{a,t}=n_{a,t-1}+\\frac{n_{a,t-1}D_{a,t}}{P_{a,t}}','Used when reinvestment is on.'),\n ('Sleeve and portfolio value',r'V_{a,t}=n_{a,t}P_{a,t}+C_{a,t},\\qquad V_t=\\sum_aV_{a,t}','All downstream portfolio analytics use this reconstructed value series.'),\n ('Annual rebalance',r'n_{a,t}^{new}=\\frac{w_aV_{t^-}}{P_{a,t^-}}','At the first observation of a new year in annual-rebalanced mode.'),\n ('Portfolio periodic return',r'r_{p,t}=\\frac{V_t}{V_{t-1}}-1','Derived from reconstructed portfolio value.'),\n ('Total return',r'R_p=\\frac{V_T}{V_0}-1','Portfolio holding-period total return.'),\n ('CAGR',r'CAGR=\\left(\\frac{V_T}{V_0}\\right)^{1/Y}-1','Y is elapsed calendar years.'),\n ('Annualised volatility',r'\\sigma_{ann}=s(r_p)\\sqrt{N}','N=252 for daily and 12 for month-end observations.'),\n ('Periodic risk-free rate',r'r_{f,p}=(1+r_{f,ann})^{1/N}-1','Converts configured annual RF to observation frequency.'),\n ('Sharpe ratio',r'S=\\frac{\\overline{(r_p-r_f)}}{s(r_p-r_f)}\\sqrt{N}','Annualised excess-return Sharpe.'),\n ('Downside volatility',r'\\sigma_d=\\sqrt{\\operatorname{mean}[(r_p-r_f)^2\\mid r_p-r_f<0]}\\sqrt{N}','Only negative excess-return observations enter.'),\n ('Sortino ratio',r'Sortino=\\frac{\\overline{(r_p-r_f)}N}{\\sigma_d}','Annualised mean excess return divided by annualised downside deviation.'),\n ('Drawdown',r'DD_t=\\frac{V_t}{\\max_{s\\le t}V_s}-1,\\qquad MDD=\\min_t DD_t','Maximum drawdown is the minimum of the drawdown series.'),\n ('Calmar ratio',r'Calmar=\\frac{CAGR}{|MDD|}','CAGR divided by absolute maximum drawdown.'),\n ('Historical VaR 95%',r'VaR_{95}=Q_{0.05}(r_p)','Empirical fifth percentile of periodic returns.'),\n ('Historical CVaR 95%',r'CVaR_{95}=E[r_p\\mid r_p\\le VaR_{95}]','Mean return in the 5% left tail.'),\n ('Positive periods',r'PositiveShare=\\frac{\\#\\{t:r_{p,t}>0\\}}{\\#\\{t\\}}','Best and worst periods are max/min periodic returns.'),\n ('Annual total return',r'R_y=\\frac{V_{y,end}}{V_{y,start}}-1','First/last available observations define partial years.'),\n ('Pearson correlation',r'\\rho_{ij}=\\frac{Cov(r_i,r_j)}{\\sigma_i\\sigma_j}','Matrix uses reconstructed periodic total returns. Net inter-asset correlation is the mean unique off-diagonal correlation.'),\n ('CAPM beta',r'\\beta=\\frac{Cov(r_p-r_f,r_m-r_f)}{Var(r_m-r_f)}','Benchmark is the configured application benchmark.'),\n ('CAPM alpha',r'\\alpha_{ann}=\\left(1+\\overline{(r_p-r_f)}-\\beta\\overline{(r_m-r_f)}\\right)^N-1','Annualised from periodic CAPM intercept.'),\n ('Rolling beta',r'\\beta_t^{(W)}=\\frac{Cov_W(r_p-r_f,r_m-r_f)}{Var_W(r_m-r_f)}','W=252 daily observations or 36 month-end observations in the current implementation.'),\n ('Rolling alpha',r'\\alpha_t^{(W)}=\\left(1+\\overline{x_p}^{(W)}-\\beta_t^{(W)}\\overline{x_m}^{(W)}\\right)^N-1','Rolling annualised CAPM intercept.'),\n ('Conditional beta',r'\\beta_{cond}=\\frac{Cov(r_p,r_m\\mid DD_m\\le-10\\%)}{Var(r_m\\mid DD_m\\le-10\\%)}','Only benchmark observations in drawdowns of at least 10% are retained.'),\n ('Rolling 1Y return',r'R_{t,1Y}=\\prod_{k=t-W+1}^{t}(1+r_{p,k})-1','W=252 daily or 12 month-end observations.'),\n ('Rolling 1Y volatility',r'\\sigma_{t,1Y}=s_W(r_p)\\sqrt{N}','Rolling one-year annualised volatility.'),\n ('Rolling 3Y Sharpe',r'S_{t,3Y}=\\frac{\\overline{x_p}^{(W_3)}}{s_{W_3}(x_p)}\\sqrt{N}','W3=756 daily or 36 month-end observations.'),\n ('Portfolio weights',r'w_{a,t}=\\frac{V_{a,t}}{V_t}','Used for ending-weight / drift reporting.')\n ]\n for title,eq,note in sections:\n  st.subheader(title); st.latex(eq); st.write(note)\n st.subheader('Current configured outputs')\n st.dataframe(metric_table(met),hide_index=True,use_container_width=True)\n st.subheader('Current instruments')\n st.dataframe(pd.DataFrame([{'Instrument Name':instrument_name(a),'Ticker / Series':a,'Initial Weight':weights[a]} for a in ASSETS]),hide_index=True,use_container_width=True)\n'''
s=s[:ls]+latex+s[le:]
# Audit: explicit source mapping and no claim that everything is Yahoo.
s=s.replace("st.header('Sources & transformations');", "st.header('Sources & transformations'); st.dataframe(pd.DataFrame([{'Instrument Name':instrument_name(a),'Ticker / Series':a,'Source':'SARB / repository' if a=='GOVI' else 'Market-data adapter'} for a in ASSETS]),hide_index=True,use_container_width=True);",1)
# Regression guards.
required=['Complete Calculation Workings','Pearson Correlation Matrix','Instrument Name','Ticker / Series','Search asset','KBP2013M','Capital Gain % of Total','Income % of Total']
missing=[x for x in required if x not in s]
if missing: raise SystemExit('missing required architecture: '+repr(missing))
if 'FX Attribution' in s or 'fx_decomposition' in s or 'history_metadata' in s: raise SystemExit('forbidden regression detected')
p.write_text(s)
print('SOURCE-AWARE / FULL-WORKINGS PATCH: PASS')
